/**
 * Embedded official ByteBeacon logo (base64 PNG).
 * Self-contained so email delivery never fails from filesystem or path resolution issues.
 */
import fs from 'fs';
import path from 'path';

export const BYTEBEACON_LOGO_BASE64 = '';

let cachedBuffer: Buffer | null = null;

export function getByteBeaconLogoBuffer(): Buffer {
  if (cachedBuffer) {
    return cachedBuffer;
  }

  const candidatePaths = [
    path.resolve(process.cwd(), 'apps/frontend/public/logo.png'),
    path.resolve(process.cwd(), '../frontend/public/logo.png'),
    path.resolve(process.cwd(), 'public/logo.png'),
  ];

  for (const p of candidatePaths) {
    try {
      if (fs.existsSync(p)) {
        cachedBuffer = fs.readFileSync(p);
        return cachedBuffer;
      }
    } catch {
      // Continue to embedded fallback
    }
  }

  cachedBuffer = Buffer.from(BYTEBEACON_LOGO_BASE64, 'base64');
  return cachedBuffer;
}
